+  display:grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 14px;
+}
+.kpi .card{ border-radius: 22px; padding: 18px; }
+.kpi .num{ font-size: 22px; font-weight: 900; letter-spacing: -.02em; }
+.kpi .hint{ color: rgba(11,11,16,.62); font-weight: 650; font-size: 13px; margin-top: 4px; }
+
+.accent-link{ display:inline-flex; align-items:center; gap: 8px; font-weight: 850; color: rgba(11,11,16,.86); }
+.accent-link .arrow{ width: 28px; height: 28px; border-radius: 999px; display:grid; place-items:center; background: rgba(118,56,250,.12); }
+.accent-link:hover{ text-decoration:none; }
+.accent-link:hover .arrow{ background: rgba(118,56,250,.18); }
+
+/* Safety + creators mood */
+.safety .card{ background: linear-gradient(180deg, rgba(118,56,250,.06), rgba(34,195,255,.04)), rgba(255,255,255,.86); }
+.creators .card{ background: linear-gradient(180deg, rgba(255,45,170,.08), rgba(255,122,0,.06)), rgba(255,255,255,.86); }
+
+/* Tagline banner */
+.tagline{
+  padding: 46px 0;
+}
+.tagline-inner{
+  border-radius: var(--radius-lg);
+  padding: 28px 22px;
+  border: 1px solid rgba(11,11,16,.10);
+  background:
+    radial-gradient(900px 220px at 15% 50%, rgba(118,56,250,.18), transparent 55%),
+    radial-gradient(900px 220px at 75% 50%, rgba(255,122,0,.14), transparent 55%),
