+  box-shadow: 0 18px 46px rgba(13, 10, 28, .12);
+  display:flex;
+  align-items:center;
+  justify-content: space-between;
+  gap: 18px;
+}
+.tagline strong{ font-size: 18px; letter-spacing: -.01em; }
+.tagline span{ color: rgba(11,11,16,.68); }
+
+/* News carousel */
+.news-shell{
