+  border: 1px solid rgba(11,11,16,.10);
+  background: rgba(255,255,255,.78);
+  box-shadow: var(--shadow);
+  padding: 18px;
+}
+.news-top{
+  display:flex;
+  align-items:flex-end;
+  justify-content: space-between;
+  gap: 18px;
+  padding: 10px 8px 16px;
+}
+.news-top .meta{ display:flex; flex-direction: column; gap: 8px; }
+.news-actions{ display:flex; align-items:center; gap: 10px; flex-wrap: wrap; }
+.carousel-controls{ display:flex; gap: 8px; }
+.carousel-btn{
+  width: 44px;
+  height: 44px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,11,16,.14);
+  background: rgba(255,255,255,.88);
+  cursor:pointer;
+}
+.carousel-btn:disabled{ opacity: .45; cursor:not-allowed; }
+.carousel-btn:focus-visible{ outline: 3px solid rgba(118,56,250,.35); outline-offset: 2px; }
+
+.carousel{
+  display:grid;
+  grid-auto-flow: column;
+  grid-auto-columns: minmax(280px, 360px);
+  gap: 14px;
+  overflow-x: auto;
+  padding: 10px;
+  scroll-snap-type: x mandatory;
+  scroll-padding: 10px;
+  -webkit-overflow-scrolling: touch;
+}
+.carousel:focus-visible{ outline: 3px solid rgba(118,56,250,.35); outline-offset: 6px; border-radius: 16px; }
