+.carousel::-webkit-scrollbar-thumb{ background: rgba(11,11,16,.18); border-radius: 999px; }
+.carousel::-webkit-scrollbar-track{ background: rgba(11,11,16,.06); border-radius: 999px; }
+
+.news-card{
+  scroll-snap-align: start;
+  border-radius: 22px;
+  border: 1px solid rgba(11,11,16,.10);
+  background: rgba(255,255,255,.92);
+  overflow:hidden;
+  box-shadow: 0 14px 34px rgba(13, 10, 28, .10);
+  transition: transform 170ms var(--ease);
+}
+.news-card:hover{ transform: translateY(-2px); }
+.thumb{
+  height: 150px;
+  background:
+    radial-gradient(260px 120px at 18% 35%, rgba(255,255,255,.85), rgba(255,255,255,0) 60%),
+    linear-gradient(120deg, rgba(118,56,250,1), rgba(255,45,170,1), rgba(255,122,0,1));
