+.thumb.variant-3{ background: radial-gradient(260px 120px at 22% 35%, rgba(255,255,255,.85), rgba(255,255,255,0) 60%), linear-gradient(120deg, rgba(255,122,0,1), rgba(255,45,170,1), rgba(118,56,250,1)); }
+.thumb.variant-4{ background: radial-gradient(260px 120px at 22% 35%, rgba(255,255,255,.85), rgba(255,255,255,0) 60%), linear-gradient(120deg, rgba(118,56,250,1), rgba(34,195,255,1), rgba(255,122,0,1)); }
