+  font-size: 12px;
+  font-weight: 850;
+  letter-spacing: .02em;
+  border: 1px solid rgba(11,11,16,.12);
+  background: rgba(118,56,250,.08);
+  color: rgba(11,11,16,.82);
+}
+.tag.orange{ background: rgba(255,122,0,.10); }
+.tag.cyan{ background: rgba(34,195,255,.10); }
+.news-title{ font-weight: 850; letter-spacing: -.01em; font-size: 16px; color: rgba(11,11,16,.92); }
+.news-date{ font-weight: 750; font-size: 13px; color: rgba(11,11,16,.56); }
+
+/* Download CTA */
+.download{
+  padding: 84px 0;
+}
+.download-inner{
+  border-radius: calc(var(--radius-lg) + 10px);
+  border: 1px solid rgba(11,11,16,.10);
+  background:
+    radial-gradient(900px 360px at 20% 0%, rgba(118,56,250,.22), transparent 55%),
+    radial-gradient(900px 360px at 90% 10%, rgba(255,122,0,.18), transparent 55%),
+    rgba(255,255,255,.82);
+  box-shadow: var(--shadow);
+  padding: 30px;
+  display:flex;
+  align-items:center;
+  justify-content: space-between;
+  gap: 22px;
+}
+.download h2{ margin-bottom: 10px; }
+.download .sub{ font-size: 20px; font-weight: 850; letter-spacing: -.02em; color: rgba(11,11,16,.84); }
+
+/* Footer */
+footer{ padding: 54px 0 32px; border-top: 1px solid rgba(11,11,16,.08); background: rgba(255,255,255,.62); }
+.footer-grid{
+  display:grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 18px;
+}
+.footer-col{ padding: 10px; }
+.footer-col h4{ margin: 0 0 10px; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: rgba(11,11,16,.66); }
+.footer-col a{
+  display:block;
+  padding: 8px 0;
+  color: rgba(11,11,16,.78);
+  font-weight: 650;
+  font-size: 14px;
+}
+.footer-col a:hover{ text-decoration: underline; }
+.footer-bottom{
+  margin-top: 18px;
+  padding-top: 16px;
+  border-top: 1px solid rgba(11,11,16,.08);
+  display:flex;
+  align-items:center;
+  justify-content: space-between;
+  gap: 14px;
+  flex-wrap: wrap;
+}
+.select{
+  display:flex;
+  align-items:center;
+  gap: 8px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,11,16,.12);
+  padding: 10px 12px;
+  background: rgba(255,255,255,.78);
+  font-weight: 750;
+}
+.icons{ display:flex; gap: 10px; flex-wrap: wrap; }
+.soc{
+  width: 40px;
+  height: 40px;
+  border-radius: 999px;
+  border: 1px solid rgba(11,11,16,.12);
+  background: rgba(255,255,255,.84);
+  display:grid;
+  place-items:center;
+  font-weight: 900;
+  font-size: 12px;
+}
+.legal{ display:flex; gap: 12px; flex-wrap: wrap; }
+.legal a{ color: rgba(11,11,16,.66); font-weight: 700; font-size: 13px; }
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{ grid-template-columns: 1fr; }
+  .hero-visual{ height: 360px; }
+  .split{ grid-template-columns: 1fr; }
+  section{ padding: 72px 0; }
+  .footer-grid{ grid-template-columns: repeat(3, minmax(0, 1fr)); }
+}
+
+@media (max-width: 720px){
+  .nav{ display:none; }
+  .hamburger{ display:inline-grid; place-items:center; }
+  .download-inner{ flex-direction: column; align-items:flex-start; }
+  .tagline-inner{ flex-direction: column; align-items:flex-start; }
+  .footer-grid{ grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .news-top{ flex-direction: column; align-items:flex-start; }
+}
+
+@media (prefers-reduced-motion: reduce){
+  html{ scroll-behavior: auto; }
+  .btn, .news-card{ transition: none; }
+}
+
*** End Patch
PATCH

